// Attributes the bytes of a dart2js bundle to the packages they came from.
//
// Reads `main.dart.js` and its source map from a Flutter web build made with
// `--source-maps`, gives every generated byte to the source file of the
// mapping segment it falls in, and prints the packages (and, with --files,
// the files) that cost the most.
//
//   node tools/perf/js_size_by_package.mjs <build/web> [--top 30] [--files]
//     [--json]
//
// Bytes no mapping covers (runtime helpers, constant pools) are reported as
// "(unmapped)". Use it to pick what to move behind a deferred import.

import { readFileSync } from "node:fs";
import { join } from "node:path";

const args = process.argv.slice(2);
const dir = args[0];
if (!dir) {
  console.error("usage: node tools/perf/js_size_by_package.mjs <build/web> [--top N] [--files] [--json]");
  process.exit(2);
}
const option = (name, fallback) => {
  const index = args.indexOf(`--${name}`);
  return index === -1 ? fallback : args[index + 1];
};
const top = Number(option("top", "30"));
const byFile = args.includes("--files");
const asJson = args.includes("--json");
const bundle = option("bundle", "main.dart.js");

const js = readFileSync(join(dir, bundle), "utf8");
const map = JSON.parse(readFileSync(join(dir, `${bundle}.map`), "utf8"));

const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
const values = new Map([...chars].map((c, i) => [c, i]));
function decode(segment) {
  const out = [];
  let value = 0;
  let shift = 0;
  for (const c of segment) {
    const digit = values.get(c);
    value += (digit & 31) << shift;
    if (digit & 32) {
      shift += 5;
    } else {
      out.push(value & 1 ? -(value >> 1) : value >> 1);
      value = 0;
      shift = 0;
    }
  }
  return out;
}

function owner(source) {
  if (source === undefined) return "(unmapped)";
  const pkg = source.match(/(?:^|\/)packages\/([^/]+)\//)
    ?? source.match(/pub-cache\/hosted\/[^/]+\/([^/]+?)-\d[^/]*\//);
  if (pkg) return pkg[1];
  if (source.includes("dart-sdk/lib/") || source.startsWith("org-dartlang-sdk:")) {
    const lib = source.match(/lib\/(_internal\/[^/]+|[^/]+)\//);
    return `dart:${lib ? lib[1] : "sdk"}`;
  }
  if (source.includes("/flutter/packages/flutter/")) return "flutter";
  if (source.includes("flutter_web_sdk") || source.includes("/lib/_engine/") || source.includes("/lib/ui/")) {
    return "flutter (web engine)";
  }
  const workspace = source.match(/(?:^|\/)(openbudget_[a-z_]+)\//);
  if (workspace) return workspace[1];
  // The app's own files are mapped relative to the build directory.
  if (/^(\.\.\/)+lib\//.test(source)) return "openbudget_app";
  return source;
}

const lines = js.split("\n");
const mappingLines = map.mappings.split(";");
const totals = new Map();
let sourceIndex = 0;
for (let lineNo = 0; lineNo < lines.length; lineNo++) {
  const line = lines[lineNo];
  const lineBytes = Buffer.byteLength(line, "utf8") + 1;
  const segments = (mappingLines[lineNo] ?? "").split(",").filter(Boolean);
  let column = 0;
  const points = [];
  for (const segment of segments) {
    const fields = decode(segment);
    column += fields[0];
    if (fields.length >= 4) {
      sourceIndex += fields[1];
      points.push([column, sourceIndex]);
    } else {
      points.push([column, undefined]);
    }
  }
  if (points.length === 0 || points[0][0] > 0) points.unshift([0, undefined]);
  for (let i = 0; i < points.length; i++) {
    const start = points[i][0];
    const end = i + 1 < points.length ? points[i + 1][0] : line.length;
    // Columns count UTF-16 units; the bundle is ASCII apart from string data.
    const bytes = Math.max(0, end - start) + (i + 1 === points.length ? lineBytes - line.length : 0);
    const source = points[i][1] === undefined ? undefined : map.sources[points[i][1]];
    const key = byFile ? (source ?? "(unmapped)") : owner(source);
    totals.set(key, (totals.get(key) ?? 0) + bytes);
  }
}

const total = Buffer.byteLength(js, "utf8");
const rows = [...totals.entries()].sort((a, b) => b[1] - a[1]);
if (asJson) {
  console.log(JSON.stringify({ total, rows: rows.slice(0, top) }, null, 2));
} else {
  console.log(`${bundle}: ${(total / 1e6).toFixed(2)} MB`);
  for (const [key, bytes] of rows.slice(0, top)) {
    console.log(
      `${(bytes / 1e3).toFixed(0).padStart(7)} KB  ${((100 * bytes) / total).toFixed(1).padStart(5)}%  ${key}`,
    );
  }
}
